import type { App } from 'vue'
import type { RecentImage } from './types/recentImage'

let app: App | null = null
let mounting = false

/**
 * Read the recent images the PHP template embedded for the start page.
 *
 * The JSON is generated by the server, but it is still validated here so a
 * malformed value cannot break rendering.
 */
export function readRecentImages(container: HTMLElement): RecentImage[] {
  const raw = container.dataset.recentImages
  if (!raw) {
    return []
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(raw)
  } catch {
    return []
  }

  if (!Array.isArray(parsed)) {
    return []
  }

  return parsed.filter((item): item is RecentImage => {
    const image = item as Partial<RecentImage> | null
    return (
      typeof image === 'object'
      && image !== null
      && typeof image.id === 'number'
      && typeof image.name === 'string'
      && typeof image.path === 'string'
      && typeof image.extension === 'string'
      && typeof image.mtime === 'number'
    )
  })
}

/**
 * The file id the editor should open, from the container or the query string.
 */
export function resolveFileId(container: HTMLElement): string | null {
  const fromContainer = container.dataset.fileIds
  if (fromContainer) {
    return fromContainer
  }

  const params = new URLSearchParams(window.location.search)
  return params.get('fileIds') ?? params.get('fileId')
}

/**
 * Mount the editor into a container element.
 *
 * Vue and the editor component are imported lazily so this module (which is
 * loaded as an init script on every Files page) stays small; the editor bundle
 * is only fetched when the app's own page actually renders a container.
 */
export async function mountEditorApp(container: HTMLElement): Promise<void> {
  if (app !== null || mounting) {
    return
  }
  mounting = true

  try {
    const [{ createApp }, { default: PhotoEditorApp }] = await Promise.all([
      import('vue'),
      import('./App.vue'),
    ])

    app = createApp(PhotoEditorApp, { fileId: resolveFileId(container) })
    app.mount(container)
  } finally {
    mounting = false
  }
}

/**
 * Mount the start page (recent images + a link to Files).
 */
export async function mountStartPage(container: HTMLElement): Promise<void> {
  if (app !== null || mounting) {
    return
  }
  mounting = true

  try {
    const [{ createApp }, { default: StartPage }] = await Promise.all([
      import('vue'),
      import('./StartPage.vue'),
    ])

    app = createApp(StartPage, { recent: readRecentImages(container) })
    app.mount(container)
  } finally {
    mounting = false
  }
}
